import heapq

def dijkstra(n, edges, start):
    graph = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    return dist

def main():
    n, q, s = map(int, input().split())
    edges = []
    for _ in range(q):
        plan = list(map(int, input().split()))
        t = plan[0]
        if t == 1:
            v, u, w = plan[1], plan[2], plan[3]
            edges.append((v, u, w))
        elif t == 2:
            v, l, r, w = plan[1], plan[2], plan[3], plan[4]
            for i in range(l, r + 1):
                edges.append((v, i, w))
        elif t == 3:
            v, l, r, w = plan[1], plan[2], plan[3], plan[4]
            for i in range(l, r + 1):
                edges.append((i, v, w))

    dist = dijkstra(n, edges, s)
    print(' '.join(str(d if d != float('inf') else -1) for d in dist[1:]))

if __name__ == "__main__":
    main()
